"""Top-N filtering for word counts (pure logic, no I/O)."""


def filter_top_words(counts, n):
    """Return a NEW mapping containing only the n most frequent words.

    Ties are broken alphabetically: when words tie at the cutoff, the
    word earlier in alphabetical order wins. ``counts`` is not modified.
    """
    if n <= 0:
        return {}
    ranked = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    return dict(ranked[:n])

"""Top-word selection for the wordstats mock project."""


def select_top(counts, n):
    """Return a new mapping keeping only the n most frequent words.

    Words are ordered by descending count, then ascending word, and the
    first n are kept. The input mapping is not modified.
    """
    if isinstance(n, bool) or not isinstance(n, int) or n < 1:
        raise ValueError("N must be a positive integer")
    ordered = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    return dict(ordered[:n])

"""Top-N filtering for word counts (pure logic, no I/O)."""


def filter_top_words(counts, n):
    """Return a new mapping containing at most the n most frequent words.

    Entries are ranked by descending count and then ascending word, so an
    alphabetically earlier word wins when counts tie at the cutoff. The input
    mapping is not modified.
    """
    if n <= 0:
        return {}
    ranked = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    return dict(ranked[:n])

